-- P4a T3 (Lane C) 列形捕获 seed：终审登记的三列形缺口 → 本件实抓。
-- 形 1 ENUM>255 成员（2B packlen，300 成员逐字展开）/ 形 2 GEOMETRY 三型非空 + SRID 探针
-- 形 3 LONGBLOB >64KB（4B prefix + 跨页 payload，确定性 REPEAT）。
-- 仅 8.0 主闸（P4A=1 bash tools/run-difftest.sh）；5.6/5.7 矩阵面不在本 lane。
SET SESSION sql_mode='';            -- 与主 gen-data 同口径（tools/gen-data.sql 头部）
SET NAMES utf8mb4;
DROP DATABASE IF EXISTS p4a;
CREATE DATABASE IF NOT EXISTS p4a CHARACTER SET utf8mb4;
USE p4a;

-- ============================================================
